 await check('Terminal target: replacing chosen element after wheel fails its original identity',async()=>{await go('terminal-long-usage');const wheel=page.mouse.wheel.bind(page.mouse);let replaced=false;page.mouse.wheel=async(...args)=>{await wheel(...args);if(!replaced){replaced=true;await page.locator('#summary').evaluate(node=>node.replaceWith(node.cloneNode(true)));}};try{await assert.rejects(scroll(terminalInput()),/Far target identity must remain/);}finally{page.mouse.wheel=wheel;}assert.equal(replaced,true);});
 await check('Terminal target: foreign candidate rejects before any wheel',async()=>{await go('terminal-layout');let wheeled=false;const wheel=page.mouse.wheel.bind(page.mouse);page.mouse.wheel=async(...args)=>{wheeled=true;return wheel(...args);};try{await assert.rejects(scroll({...terminalInput(),target:args=>terminal({...args,candidates:[...terminalCandidates(),page.locator('#outside')]})}));}finally{page.mouse.wheel=wheel;}assert.equal(wheeled,false);});
 await check('Terminal target: hidden endpoint cannot disappear from measurement silently',async()=>{await go('terminal-layout');await page.locator('#summary').evaluate(node=>{node.hidden=true;});await assert.rejects(scroll(terminalInput()));});
 await check('Terminal target: fixed locator and unchanged default owner contract still prove actual wheel',async()=>{await go('modal');const result=await scroll({...base,container:page.locator('#body'),target:page.locator('#submit'),axis:'y',containment:'modal-lock'});assert.ok(result.observations.every(r=>r.actualWheelMoved&&r.targetHitTestPassed&&r.farBoundaryReached));});
 await check('Terminal target: resolver refuses an unimplemented horizontal endpoint policy',async()=>{await go('terminal-layout');await assert.rejects(terminal({container:page.locator('#body'),candidates:terminalCandidates(),axis:'x'}));});
 if(terminalOnly)assert.equal(checks.length,8);

